#!/usr/bin/env node
import { Command } from 'commander';
import chalk from 'chalk';
import ora from 'ora';
import { performance } from 'perf_hooks';
import { registerCommit } from './commands/commit.js';
import { registerReview } from './commands/review.js';
import { registerResolve } from './commands/resolve.js';
import { registerBranch } from './commands/branch.js';
import { registerPR } from './commands/pr.js';
import { registerUI } from './commands/ui.js';
import { registerHistory } from './commands/history.js';
import { registerClean } from './commands/clean.js';
import { registerImpact } from './commands/impact.js';
import { registerPlugin } from './commands/plugin.js';
import { registerPair } from './commands/pair.js';
import { registerRemote } from './commands/remote.js';
import { registerScan } from './commands/scan.js';
import { registerStash } from './commands/stash.js';
import { registerRelease } from './commands/release.js';
import { registerFun } from './commands/fun.js';
import { registerHooks } from './commands/hooks.js';
import { registerSync } from './commands/sync.js';
import { loadPlugins } from './plugins/loader.js';
import { recordCommand, suggestNextCommand, inlineSuggestion } from './utils/history.js';
import { suggestCommand } from './utils/suggest.js';
import { detectTamper } from './utils/guard.js';
import pkg from '../package.json' with { type: 'json' };

const program = new Command();
program
  .name('gitcli')
  .description('Git supercharged with AI and plugins')
  .version(pkg.version)
  .showSuggestionAfterError(true);

const inline = inlineSuggestion(process.argv.slice(2).join(' '));
if (inline) {
  console.log(chalk.gray(`Hint from history: ${inline}`));
}

registerCommit(program);
registerReview(program);
registerResolve(program);
registerBranch(program);
registerPR(program);
registerUI(program);
registerHistory(program);
registerClean(program);
registerImpact(program);
registerPlugin(program);
registerPair(program);
registerRemote(program);
registerScan(program);
registerStash(program);
registerRelease(program);
registerFun(program);
registerHooks(program);
registerSync(program);

await loadPlugins(program);
await detectTamper();

program.on('command:*', () => {
  const unknown = program.args.join(' ');
  const cmds = program.commands.map(c => c.name());
  const suggestion = suggestCommand(unknown, cmds);
  if (suggestion) {
    console.log(chalk.yellow(`Did you mean ${suggestion}?`));
  }
});

const start = performance.now();
program.hook('postAction', () => {
  const duration = performance.now() - start;
  const executed = process.argv.slice(2).join(' ');
  recordCommand(executed, duration);
  const suggestion = suggestNextCommand();
  if (suggestion) {
    console.log(chalk.gray(`Next likely command: ${suggestion}`));
  }
});

const spinner = ora();
spinner.stop();
program.parseAsync(process.argv);
